import { Type, type TSchema } from "typebox";
import type { ExtensionAPI, ExtensionToolContext, ToolDefinition } from "@earendil-works/pi-coding-agent";
import { accessSync, constants, mkdirSync } from "node:fs";
import { join } from "node:path";
import type { GraphStore } from "./graph/store.js";
import { SqliteGraphStore } from "./graph/sqlite.js";
import { indexProject } from "./indexer/pipeline.js";
import { resolveMissingCallers, resolveImplementations } from "./indexer/lsp-resolver.js";
import { TsServerClient } from "./indexer/tsserver-client.js";
import { symbolGraph } from "./tools/symbol-graph.js";
import { impact } from "./tools/impact.js";
import { trace } from "./tools/trace.js";
import { resetSearchCacheForTesting as _resetSearchCache } from "./tools/symbol-search.js";
import { appendTokenMetaIfEnabled, resetSession } from "./tools/token-tracker.js";
import { suppressFreshTrustHeader, stripTrustHeader } from "./output/read-only-ceremony.js";
import { ensureHashInit } from "./output/anchoring.js";

const SymbolGraphParams = Type.Object({
  name: Type.String({ description: "Symbol name." }),
  file: Type.Optional(Type.String({ description: "Disambiguating file path." })),
  include: Type.Optional(
    Type.Array(
      Type.Union([
        Type.Literal("neighborhood"),
        Type.Literal("contract"),
        Type.Literal("source"),
      ]),
      {
        description: "Extra sections to include.",
      },
    ),
  ),
  suppressTrustHeader: Type.Optional(
    Type.Boolean({ description: "Omit the Trust header." }),
  ),
});


const ImpactParams = Type.Object({
  symbols: Type.Array(Type.String({ description: "Changed symbol." }), {
    description: "Changed symbols.",
  }),
  changeType: Type.Union(
    [
      Type.Literal("signature_change"),
      Type.Literal("removal"),
      Type.Literal("behavior_change"),
      Type.Literal("addition"),
    ],
    { description: "Change kind." },
  ),
  maxDepth: Type.Optional(
    Type.Number({ description: "Maximum traversal depth." }),
  ),
  suppressTrustHeader: Type.Optional(
    Type.Boolean({ description: "Omit the Trust header." }),
  ),
});

const TraceParams = Type.Object({
  entry: Type.String({ description: "Entry symbol or endpoint." }),
  file: Type.Optional(Type.String({ description: "Disambiguating file path." })),
  suppressTrustHeader: Type.Optional(
    Type.Boolean({ description: "Omit the Trust header." }),
  ),
});

/**
 * Machine-readable result for programmatic callers (codemode scripts). The model still receives the
 * text; scripts get the same text plus every `file  LINE:HASH` anchor already parsed out of it.
 */
const ToolOutputSchema = Type.Object({
  text: Type.String({ description: "Full model-facing output." }),
  anchors: Type.Array(
    Type.Object({
      file: Type.String(),
      line: Type.Integer(),
      hash: Type.String({ description: "3-hex hashline hash, same algorithm as pi-hashline-readmap." }),
    }),
    { description: "Editable anchors found in the output, deduplicated." },
  ),
  indexingFailed: Type.Boolean({ description: "True when the output is prefixed by an indexing-failed note." }),
});

const CODEGRAPH_NAMESPACE = {
  name: "codegraph",
  description: "Symbol-level code graph for TypeScript: callers, callees, impact, and execution paths.",
  instructions:
    "Read-only tools backed by a SQLite graph in .codegraph/graph.db that auto-indexes the project. " +
    "Outputs carry `file  LINE:HASH` anchors that are editable with pi-hashline-readmap. " +
    "structuredContent is { text, anchors, indexingFailed }.",
};

interface ProjectState {
  store: GraphStore;
  client: TsServerClient | null;
  indexing: Promise<void> | null;
  /** In-flight LSP resolutions by node id, so concurrent calls for one symbol share the work. */
  resolving: Map<string, Promise<void>>;
}

/** One entry per project root; a session can move between roots, so nothing is keyed on the first cwd. */
const projects = new Map<string, ProjectState>();
let sharedStore: GraphStore | null = null;

interface IndexErrorRecord {
  error: Error;
  setAt: number;
}

let lastIndexError: IndexErrorRecord | null = null;
type IndexProjectFn = typeof indexProject;
let indexProjectImpl: IndexProjectFn = indexProject;
export function getSharedStoreForTesting(): GraphStore | null {
  return sharedStore;
}
export function getLastIndexErrorForTesting(): Error | null {
  return lastIndexError ? lastIndexError.error : null;
}

export function setLastIndexErrorForTesting(error: Error | null, setAt: number = Date.now()): void {
  lastIndexError = error ? { error, setAt } : null;
}

export function getIndexingFailedNoteForTesting(now: number = Date.now()): string {
  if (!lastIndexError) return "";
  const ageSeconds = Math.max(0, Math.floor((now - lastIndexError.setAt) / 1000));
  return `indexing-failed (${ageSeconds}s ago): ${lastIndexError.error.message}\n`;
}

export function setIndexProjectForTesting(fn: IndexProjectFn | null): void {
  indexProjectImpl = fn ?? indexProject;
}

/** Close every store and tsserver. Idempotent: cancellation, reload and exit can all land here. */
async function closeAllProjects(): Promise<void> {
  const states = [...projects.values()];
  projects.clear();
  sharedStore = null;
  // Let an in-flight index finish briefly rather than closing the database underneath it.
  const inflight = states.map((s) => s.indexing).filter((p): p is Promise<void> => p !== null);
  if (inflight.length > 0) {
    await Promise.race([
      Promise.allSettled(inflight),
      new Promise<void>((resolve) => setTimeout(resolve, 3000).unref?.()),
    ]);
  }
  await Promise.allSettled(states.map((s) => s.client?.shutdown()));
  for (const s of states) {
    try {
      s.store.close();
    } catch {
      // already closed
    }
  }
}

export function resetStoreForTesting(): void {
  for (const s of projects.values()) {
    try {
      s.store.close();
    } catch {
      // already closed
    }
    void s.client?.shutdown().catch(() => {});
  }
  projects.clear();
  sharedStore = null;
  lastIndexError = null;
  indexProjectImpl = indexProject;
  resetSession();
  _resetSearchCache();
}

function getOrCreateProject(projectRoot: string): ProjectState {
  const existing = projects.get(projectRoot);
  if (existing) {
    sharedStore = existing.store;
    return existing;
  }
  const dbDir = join(projectRoot, ".codegraph");
  mkdirSync(dbDir, { recursive: true });
  const state: ProjectState = { store: new SqliteGraphStore(join(dbDir, "graph.db")), client: null, indexing: null, resolving: new Map() };
  projects.set(projectRoot, state);
  sharedStore = state.store;
  return state;
}

/** One tsserver per project, started lazily. It stops itself when idle and is closed on session shutdown. */
function getClient(projectRoot: string, state: ProjectState): TsServerClient {
  state.client ??= new TsServerClient(projectRoot);
  return state.client;
}

function dbIsWritable(projectRoot: string): boolean {
  const dbDir = join(projectRoot, ".codegraph");
  try {
    accessSync(join(dbDir, "graph.db"), constants.W_OK);
    accessSync(dbDir, constants.W_OK);
    return true;
  } catch {
    return false;
  }
}

function ensureIndexed(projectRoot: string, state: ProjectState): Promise<void> {
  if (state.indexing) return state.indexing;
  const run = (async () => {
    try {
      const result = await indexProjectImpl(projectRoot, state.store);
      if (result.errors > 0 && !dbIsWritable(projectRoot)) {
        lastIndexError = { error: new Error("readonly database"), setAt: Date.now() };
      } else {
        lastIndexError = null;
      }
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err));
      lastIndexError = { error, setAt: Date.now() };
    } finally {
      state.indexing = null;
    }
  })();
  state.indexing = run;
  return run;
}

function abortReason(signal: AbortSignal): Error {
  const reason = signal.reason;
  return reason instanceof Error ? reason : new Error("codegraph: operation aborted");
}

/** Reject as soon as `signal` aborts. Shared work (indexing) keeps running for other callers. */
function raceAbort<T>(work: Promise<T>, signal: AbortSignal | undefined): Promise<T> {
  if (!signal) return work;
  if (signal.aborted) return Promise.reject(abortReason(signal));
  return new Promise<T>((resolve, reject) => {
    const onAbort = () => reject(abortReason(signal));
    signal.addEventListener("abort", onAbort, { once: true });
    work.then(
      (value) => {
        signal.removeEventListener("abort", onAbort);
        resolve(value);
      },
      (error) => {
        signal.removeEventListener("abort", onAbort);
        reject(error);
      },
    );
  });
}

function setStatus(ctx: Pick<ExtensionToolContext, "hasUI" | "ui"> | undefined, text: string | undefined): void {
  try {
    if (ctx?.hasUI) ctx.ui.setStatus("codegraph", text);
  } catch {
    // status is cosmetic
  }
}

/** Resolve the project, index it if needed, and prepare hashing. Throws if `signal` aborts. */
async function prepare(ctx: ExtensionToolContext, signal: AbortSignal | undefined) {
  signal?.throwIfAborted();
  const projectRoot = ctx.cwd;
  const state = getOrCreateProject(projectRoot);
  setStatus(ctx, "codegraph: indexing…");
  try {
    await raceAbort(ensureIndexed(projectRoot, state), signal);
  } finally {
    setStatus(ctx, lastIndexError ? "codegraph: indexing failed" : undefined);
  }
  await ensureHashInit();
  return { projectRoot, state, store: state.store };
}

function indexingFailedNote(): string {
  return getIndexingFailedNoteForTesting();
}

function finalizeReadOnlyOutput(
  toolName: string,
  params: Record<string, unknown>,
  toolOutput: string,
  store: GraphStore,
  projectRoot: string,
  suppressTrustHeader: boolean = false,
): string {
  const afterFreshStrip = suppressFreshTrustHeader(toolOutput);
  const afterHeaderStrip = suppressTrustHeader ? stripTrustHeader(afterFreshStrip) : afterFreshStrip;
  // suppressTrustHeader strips only the shared Trust block; indexingFailedNote()
  // and appendTokenMetaIfEnabled() still wrap the remaining body.
  const withIndexingNote = indexingFailedNote() + afterHeaderStrip;
  if (
    lastIndexError &&
    lastIndexError.error.message !== "readonly database" &&
    afterHeaderStrip.trim().length > 0
  ) {
    lastIndexError = null;
  }
  return appendTokenMetaIfEnabled(toolName, params, withIndexingNote, store, projectRoot);
}

const ANCHOR_LINE = /^[ \t]*(\S+)[ \t]{2}(\d+):([0-9a-f]{3})\b/;

/** Pull `file  LINE:HASH` locations out of rendered output so scripts do not have to re-parse text. */
export function extractAnchors(text: string): Array<{ file: string; line: number; hash: string }> {
  const seen = new Set<string>();
  const anchors: Array<{ file: string; line: number; hash: string }> = [];
  for (const raw of text.split("\n")) {
    const match = ANCHOR_LINE.exec(raw);
    if (!match) continue;
    const key = `${match[1]}\u0000${match[2]}:${match[3]}`;
    if (seen.has(key)) continue;
    seen.add(key);
    anchors.push({ file: match[1]!, line: Number(match[2]), hash: match[3]! });
  }
  return anchors;
}

/**
 * `isError` marks a failed lookup: a requested name that does not resolve to exactly one node, the rule every
 * tool renders by. The message and its match list stay in `content` and `structuredContent`.
 */
function toolResult(output: string, isError: boolean) {
  return {
    content: [{ type: "text" as const, text: output }],
    details: undefined,
    isError,
    structuredContent: {
      text: output,
      anchors: extractAnchors(output),
      indexingFailed: output.startsWith("indexing-failed"),
    },
  };
}

type ReadOnlyToolInput<TParams extends TSchema> = Pick<
  ToolDefinition<TParams>,
  "name" | "label" | "description" | "parameters" | "execute"
> & { promptSnippet: string; promptGuidelines: string[] };

function registerReadOnlyTool<TParams extends TSchema>(pi: ExtensionAPI, tool: ReadOnlyToolInput<TParams>): void {
  const definition: ToolDefinition<TParams> = {
    ...tool,
    namespace: CODEGRAPH_NAMESPACE,
    outputSchema: ToolOutputSchema,
    // Hints for permission extensions: reads the graph, never touches the project's files or the network.
    annotations: { readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: false },
    // No executionMode override: calls may run in parallel. Store writes are synchronous, indexing is
    // deduplicated per project, the tsserver client queues requests, and LSP resolution is shared per symbol.
  };
  pi.registerTool(definition);
}

function formatStatus(projectRoot: string, state: ProjectState | undefined): { text: string; level: "info" | "warning" } {
  if (!state) {
    return { text: `codegraph: ${projectRoot} is not indexed yet; it indexes on the first tool call.`, level: "info" };
  }
  const stats = state.store.getStatistics(projectRoot);
  const nodeTotal = Object.values(stats.nodes).reduce((a, b) => a + b, 0);
  const edgeTotal = Object.values(stats.edges).reduce(
    (a, byProvenance) => a + Object.values(byProvenance).reduce((x, y) => x + y, 0),
    0,
  );
  const lines = [
    `codegraph: ${projectRoot}`,
    `nodes: ${nodeTotal}  edges: ${edgeTotal}  files: ${stats.files.total} (${stats.files.stale} stale)`,
    state.indexing ? "indexing: in progress" : "indexing: idle",
  ];
  if (lastIndexError) lines.push(getIndexingFailedNoteForTesting().trimEnd());
  return { text: lines.join("\n"), level: lastIndexError ? "warning" : "info" };
}

export default function piCodegraph(pi: ExtensionAPI): void {
  // Older hosts and minimal test doubles may lack some registration methods; every one is optional.
  pi.on?.("session_start", () => {
    resetSession();
  });
  pi.on?.("session_shutdown", async () => {
    await closeAllProjects();
  });

  pi.registerCommand?.("codegraph", {
    description: "Show codegraph index status, or refresh the index (/codegraph [status|refresh])",
    handler: async (args, ctx) => {
      const sub = (args ?? "").trim().split(/\s+/)[0] || "status";
      if (sub !== "status" && sub !== "refresh") {
        ctx.ui.notify("Usage: /codegraph [status|refresh]", "warning");
        return;
      }
      if (sub === "refresh") {
        const state = getOrCreateProject(ctx.cwd);
        setStatus(ctx, "codegraph: indexing…");
        try {
          await ensureIndexed(ctx.cwd, state);
        } finally {
          setStatus(ctx, lastIndexError ? "codegraph: indexing failed" : undefined);
        }
      }
      const { text, level } = formatStatus(ctx.cwd, projects.get(ctx.cwd));
      ctx.ui.notify(text, level);
    },
  });

  registerReadOnlyTool(pi, {
    name: "symbol_graph",
    label: "Symbol Graph",
    description: "Summarize a symbol with relationships, tests, and key metadata.",
    promptSnippet: "Look up a TypeScript symbol: callers, callees, tests, contract, and anchored source",
    promptGuidelines: [
      "Use symbol_graph to find who calls or implements a symbol instead of chaining grep and read.",
      "symbol_graph anchors (`file  LINE:HASH`) are editable with the edit tool without re-reading the file.",
    ],
    parameters: SymbolGraphParams,
    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      const { projectRoot, state, store } = await prepare(ctx, signal);
      const nodes = store.findNodes(params.name, params.file);
      if (nodes.length === 1) {
        const resolvedNode = nodes[0]!;
        try {
          let shared = state.resolving.get(resolvedNode.id);
          if (!shared) {
            const client = getClient(projectRoot, state);
            shared = (async () => {
              try {
                await resolveMissingCallers(resolvedNode, store, projectRoot, client);
                if (resolvedNode.kind === "interface") {
                  await resolveImplementations(resolvedNode, store, projectRoot, client);
                }
              } finally {
                state.resolving.delete(resolvedNode.id);
              }
            })();
            state.resolving.set(resolvedNode.id, shared);
          }
          await raceAbort(shared, signal);
        } catch (error) {
          // A cancelled call must surface as cancelled, not as a quietly degraded result.
          signal?.throwIfAborted();
          void error;
          // Resolver writes failed (likely readonly DB) — continue with existing graph data.
        }
      }

      const text = symbolGraph({
        name: params.name,
        file: params.file,
        include: params.include as Array<"neighborhood" | "contract" | "source"> | undefined,
        store,
        projectRoot,
      });
      const output = finalizeReadOnlyOutput(
        "symbol_graph",
        { name: params.name, file: params.file },
        text,
        store,
        projectRoot,
        params.suppressTrustHeader === true,
      );
      return toolResult(output, nodes.length !== 1);
    },
  });


  registerReadOnlyTool(pi, {
    name: "impact",
    label: "Impact",
    description: "Classify blast radius for changed symbols.",
    promptSnippet: "Classify what breaks when TypeScript symbols change (breaking / behavioral / safe dependents)",
    promptGuidelines: [
      "Run impact on the symbols you are about to change before editing a shared function, class, or interface.",
    ],
    parameters: ImpactParams,
    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      const { projectRoot, store } = await prepare(ctx, signal);
      const text = impact({
        symbols: params.symbols,
        changeType: params.changeType,
        store,
        projectRoot,
        maxDepth: params.maxDepth,
      });
      const output = finalizeReadOnlyOutput(
        "impact",
        { symbols: params.symbols },
        text,
        store,
        projectRoot,
        params.suppressTrustHeader === true,
      );
      const failed = params.symbols.length === 0 || params.symbols.some((symbol) => store.findNodes(symbol).length !== 1);
      return toolResult(output, failed);
    },
  });

  registerReadOnlyTool(pi, {
    name: "trace",
    label: "Trace",
    description: "Return an execution path from an entry point, coverage-backed when available.",
    promptSnippet: "Trace the ordered call path from a TypeScript entry point, endpoint, or test",
    promptGuidelines: ["Use trace to follow what an entry point executes instead of reading each callee by hand."],
    parameters: TraceParams,
    async execute(_toolCallId, params, signal, _onUpdate, ctx) {
      const { projectRoot, store } = await prepare(ctx, signal);
      const text = trace({ entry: params.entry, file: params.file, store, projectRoot });
      const output = finalizeReadOnlyOutput(
        "trace",
        { entry: params.entry, file: params.file },
        text,
        store,
        projectRoot,
        params.suppressTrustHeader === true,
      );
      return toolResult(output, store.findNodes(params.entry, params.file).length !== 1);
    },
  });
}

import { readdirSync, readFileSync } from "node:fs";
import { join, relative, sep } from "node:path";

import type { GraphStore } from "../graph/store.js";
import { extractFile, sha256Hex } from "./tree-sitter.js";
import { runLspIndexStage } from "./lsp.js";
import { runAstGrepIndexStage } from "./ast-grep.js";
import { runCoverageIndexStage } from "./coverage.js";
import { runGitCoChangeStage } from "./git.js";
import { TsServerClient } from "./tsserver-client.js";
import type { ITsServerClient } from "./tsserver-client.js";

export interface IndexResult {
  indexed: number;
  skipped: number;
  removed: number;
  errors: number;
  timings: Record<string, number>;
}

export interface IndexProjectOptions {
  lspClientFactory?: (projectRoot: string) => ITsServerClient;
  coverageDir?: string;
}

function toPosixPath(p: string): string {
  return p.split(sep).join("/");
}

function walkTsFiles(root: string): string[] {
  const out: string[] = [];

  const walk = (dir: string) => {
    for (const ent of readdirSync(dir, { withFileTypes: true })) {
      if (ent.name === "node_modules" || ent.name === ".megapowers" || ent.name === ".git") continue;
      const full = join(dir, ent.name);

      if (ent.isDirectory()) {
        walk(full);
        continue;
      }

      if (ent.isFile() && (ent.name.endsWith(".ts") || ent.name.endsWith(".tsx"))) {
        out.push(full);
      }
    }
  };

  walk(root);
  return out;
}

export async function indexProject(
  projectRoot: string,
  store: GraphStore,
  options: IndexProjectOptions = {},
): Promise<IndexResult> {
  const timings: Record<string, number> = {};

  const tsStart = performance.now();
  const files = walkTsFiles(projectRoot);

  let indexed = 0;
  let skipped = 0;
  let removed = 0;
  let errors = 0;
  const changedFiles: string[] = [];

  const currentRel = new Set(files.map((absPath) => toPosixPath(relative(projectRoot, absPath))));
  for (const absPath of files) {
    const rel = toPosixPath(relative(projectRoot, absPath));
    try {
      const content = readFileSync(absPath, "utf8");
      const hash = sha256Hex(content);
      const existing = store.getFileHash(rel);
      if (existing === hash) {
        skipped++;
        continue;
      }
      if (existing !== null) {
        store.deleteFile(rel);
      }

      const extracted = extractFile(rel, content);
      store.addNode(extracted.module);
      for (const node of extracted.nodes) store.addNode(node);
      for (const edge of extracted.edges) store.addEdge(edge);
      store.setFileHash(rel, hash);
      changedFiles.push(rel);
      indexed++;
    } catch {
      errors++;
    }
  }

  for (const oldFile of store.listFiles()) {
    if (currentRel.has(oldFile) || oldFile.startsWith("__")) continue;
    try {
      store.deleteFile(oldFile);
      removed++;
    } catch {
      errors++;
    }
  }
  timings["tree-sitter"] = Math.round(performance.now() - tsStart);

  const lspStart = performance.now();
  const client = options.lspClientFactory ? options.lspClientFactory(projectRoot) : new TsServerClient(projectRoot);
  try {
    errors += await runLspIndexStage(store, projectRoot, client);
  } finally {
    await client.shutdown().catch(() => {});
  }
  timings["lsp"] = Math.round(performance.now() - lspStart);
  const astGrepStart = performance.now();
  errors += await runAstGrepIndexStage(store, projectRoot, changedFiles);
  timings["ast-grep"] = Math.round(performance.now() - astGrepStart);
  const coverageStart = performance.now();
  runCoverageIndexStage(store, projectRoot, options.coverageDir ?? join(projectRoot, ".codegraph", "coverage"));
  timings["coverage"] = Math.round(performance.now() - coverageStart);
  const gitStart = performance.now();
  errors += await runGitCoChangeStage(store, projectRoot);
  timings["git"] = Math.round(performance.now() - gitStart);

  return { indexed, skipped, removed, errors, timings };
}

// Back-compat with the existing placeholder export test
export const IndexPipeline = indexProject;

import type { GraphEdge } from "../graph/types.js";
import type { GraphStore } from "../graph/store.js";
import type { ITsServerClient } from "./tsserver-client.js";

function parseEvidence(evidence: string): { name: string; line: number; col: number } | null {
  const parts = evidence.split(":");
  if (parts.length !== 3) return null;
  const [name, lineStr, colStr] = parts;
  const line = Number(lineStr);
  const col = Number(colStr);
  if (!name || !Number.isFinite(line) || !Number.isFinite(col)) return null;
  return { name, line, col };
}

function isStartupError(err: unknown): boolean {
  return err instanceof Error && err.message.startsWith("TsServer failed to start:");
}

function isUnresolvedTarget(target: string): boolean {
  return target.startsWith("__unresolved__::");
}

function makeLspEdge(source: string, target: string, evidence: string, contentHash: string): GraphEdge {
  return {
    source,
    target,
    kind: "calls",
    provenance: {
      source: "lsp",
      confidence: 0.9,
      evidence,
      content_hash: contentHash,
    },
    created_at: Date.now(),
  };
}

export async function runLspIndexStage(
  store: GraphStore,
  _projectRoot: string,
  client: ITsServerClient,
): Promise<number> {
  let errors = 0;
  const unresolved = store.getUnresolvedEdges().filter((e) => e.kind === "calls" && e.provenance.source === "tree-sitter");
  const confirmed: GraphEdge[] = [];
  for (const file of store.listFiles()) {
    for (const node of store.getNodesByFile(file)) {
      for (const e of store.getEdgesBySource(node.id)) {
        if (e.kind === "calls" && e.provenance.source === "tree-sitter" && !isUnresolvedTarget(e.target)) {
          confirmed.push(e);
        }
      }
    }
  }
  const work = [...unresolved, ...confirmed];
  for (const edge of work) {
    const sourceNode = store.getNode(edge.source);
    if (!sourceNode) continue;
    const parsed = parseEvidence(edge.provenance.evidence);
    if (!parsed) continue;
    let loc;
    try {
      loc = await client.definition(sourceNode.file, parsed.line, parsed.col);
    } catch (err) {
      if (isStartupError(err)) return errors;
      continue;
    }
    if (!loc) continue;
    if (isUnresolvedTarget(edge.target)) {
      const targetNode = store
        .getNodesByFile(loc.file)
        .find((n) => n.name === parsed.name && n.start_line === loc.line);
      if (!targetNode) continue;
      try {
        store.deleteEdge(edge.source, edge.target, edge.kind, edge.provenance.source);
        store.addEdge(makeLspEdge(edge.source, targetNode.id, `${loc.file}:${loc.line}:${loc.col}`, sourceNode.content_hash));
      } catch {
        errors++;
      }
      continue;
    }
    const existingTarget = store.getNode(edge.target);
    if (!existingTarget) continue;
    const sameTarget = existingTarget.file === loc.file && existingTarget.start_line === loc.line;
    if (!sameTarget) continue;
    try {
      store.deleteEdge(edge.source, edge.target, edge.kind, edge.provenance.source);
      store.addEdge(makeLspEdge(edge.source, edge.target, `${loc.file}:${loc.line}:${loc.col}`, sourceNode.content_hash));
    } catch {
      errors++;
    }
  }
  return errors;
}

import { spawn as nodeSpawn } from "node:child_process";
import { getAstGrepBinary } from "./ast-grep-binary.js";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { isAbsolute, join, relative } from "node:path";
import { parse as parseYaml } from "yaml";
import type { GraphStore } from "../graph/store.js";
import type { GraphNode } from "../graph/types.js";

export interface AstGrepRule {
  name: string;
  pattern: string;
  lang: string;
  produces: {
    edge_kind: "routes_to" | "renders";
    from_capture?: string;
    from_context?: "enclosing_function";
    to_capture?: string;
    to_template?: string;
    confidence: number;
  };
}

export interface LoadRulesOptions {
  bundledDir: string;
  projectRoot: string;
}

function listRuleFiles(dir: string): string[] {
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((name) => name.endsWith(".yaml") || name.endsWith(".yml"))
    .map((name) => join(dir, name));
}

function validateRuleFile(filePath: string, raw: unknown): AstGrepRule[] {
  if (!Array.isArray(raw)) throw new Error(`Invalid rule file ${filePath}: expected YAML array`);
  return raw.map((entry) => {
    if (!entry || typeof entry !== "object") throw new Error(`Invalid rule file ${filePath}: expected object item`);
    const rule = entry as any;
    if (!rule.name) throw new Error(`Invalid rule file ${filePath}: missing name`);
    if (!rule.pattern) throw new Error(`Invalid rule file ${filePath}: missing pattern`);
    if (!rule.lang) throw new Error(`Invalid rule file ${filePath}: missing lang`);
    if (!rule.produces?.edge_kind) throw new Error(`Invalid rule file ${filePath}: missing produces.edge_kind`);
    const allowedEdgeKinds = ["routes_to", "renders"];
    if (!allowedEdgeKinds.includes(rule.produces.edge_kind)) {
      throw new Error(`Invalid rule file ${filePath}: unsupported produces.edge_kind ${rule.produces.edge_kind}`);
    }
    if (typeof rule.produces?.confidence !== "number") throw new Error(`Invalid rule file ${filePath}: missing produces.confidence`);
    const hasFromCapture = typeof rule.produces.from_capture === "string";
    const hasFromContext = typeof rule.produces.from_context === "string";
    if (hasFromCapture === hasFromContext) {
      throw new Error(`Invalid rule file ${filePath}: specify exactly one of produces.from_capture or produces.from_context`);
    }
    const hasToCapture = typeof rule.produces.to_capture === "string";
    const hasToTemplate = typeof rule.produces.to_template === "string";
    if (hasToCapture === hasToTemplate) {
      throw new Error(`Invalid rule file ${filePath}: specify exactly one of produces.to_capture or produces.to_template`);
    }
    if (hasFromContext && rule.produces.from_context !== "enclosing_function") {
      throw new Error(`Invalid rule file ${filePath}: unsupported produces.from_context ${rule.produces.from_context}`);
    }
    return rule as AstGrepRule;
  });
}

export function readRuleFile(filePath: string, _runtime?: unknown): AstGrepRule[] {
  let raw: unknown;
  try {
    const content = readFileSync(filePath, "utf8");
    raw = parseYaml(content);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid rule file ${filePath}: ${message}`);
  }
  return validateRuleFile(filePath, raw);
}

export function loadRules(options: LoadRulesOptions): AstGrepRule[] {
  const userDir = join(options.projectRoot, ".codegraph", "rules");
  const files = [...listRuleFiles(options.bundledDir), ...listRuleFiles(userDir)];
  return files.flatMap((f) => readRuleFile(f)).sort((a, b) => a.name.localeCompare(b.name));
}

interface RawSgMatch {
  file: string;
  range: { start: { line: number; column: number } };
  metaVariables?: {
    single?: Record<string, { text: string }>;
    multi?: Record<string, Array<{ text: string }>>;
  };
}

export interface SgMatch {
  file: string;
  line: number;
  column: number;
  metaVariables: Record<string, string | string[]>;
}

export type ExecFn = (cmd: string[], opts: { cwd: string }) => Promise<string>;

async function defaultExec(cmd: string[], opts: { cwd: string }): Promise<string> {
  return await new Promise<string>((resolve, reject) => {
    const child = nodeSpawn(cmd[0]!, cmd.slice(1), { cwd: opts.cwd, stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk) => { stdout += chunk; });
    child.stderr.on("data", (chunk) => { stderr += chunk; });
    child.on("error", (error) => {
      reject(new Error(`Failed to launch ast-grep: ${error.message}. Run npm install to get the bundled @ast-grep/cli, or install ast-grep on PATH (brew install ast-grep).`));
    });
    child.on("close", (code) => {
      const exitCode = code ?? 0;
      // sg exits 1 when no matches found (like grep) — treat 0 and 1 as success
      if (exitCode > 1) reject(new Error(`sg failed (${exitCode}): ${stderr.trim() || stdout.trim()}`));
      else resolve(stdout);
    });
  });
}

function toProjectRelative(projectRoot: string, file: string): string {
  if (!isAbsolute(file)) return file;
  return relative(projectRoot, file).split("\\").join("/");
}

function normalizeSgMatch(projectRoot: string, raw: RawSgMatch): SgMatch {
  if (!raw.range?.start) throw new Error("Invalid sg JSON output: missing range.start");
  const metaVariables: Record<string, string | string[]> = {};
  for (const [k, v] of Object.entries(raw.metaVariables?.single ?? {})) metaVariables[k] = v.text;
  for (const [k, v] of Object.entries(raw.metaVariables?.multi ?? {})) metaVariables[k] = v.map((x) => x.text);
  return {
    file: toProjectRelative(projectRoot, raw.file),
    line: raw.range.start.line + 1,
    column: raw.range.start.column + 1,
    metaVariables,
  };
}

export async function runScan(
  projectRoot: string,
  rule: AstGrepRule,
  files: string[],
  execFn: ExecFn = defaultExec,
): Promise<SgMatch[]> {
  if (files.length === 0) return [];
  const cmd = [getAstGrepBinary(), "run", "--json", "--lang", rule.lang, "--pattern", rule.pattern, ...files];
  let stdout: string;
  try {
    stdout = await execFn(cmd, { cwd: projectRoot });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`sg invocation failed: ${message}`);
  }
  // sg outputs empty string (not "[]") when no matches found — treat as empty result
  if (!stdout.trim()) return [];
  let parsed: unknown;
  try {
    parsed = JSON.parse(stdout);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid sg JSON output: ${message}`);
  }
  if (!Array.isArray(parsed)) throw new Error("Invalid sg JSON output: expected array");
  return (parsed as RawSgMatch[]).map((raw) => normalizeSgMatch(projectRoot, raw));
}

function metaValue(meta: Record<string, string | string[]>, key: string): string | null {
  const value = meta[key];
  if (typeof value === "string") return value;
  if (Array.isArray(value) && value.length > 0) return String(value[0]);
  return null;
}

function metaValues(meta: Record<string, string | string[]>, key: string): string[] {
  const value = meta[key];
  if (typeof value === "string") return [value];
  if (Array.isArray(value)) return value.map(String);
  return [];
}

function renderTemplate(template: string, meta: Record<string, string | string[]>): string {
  return template.replace(/\{([A-Z_]+)\}/g, (_, key: string) => {
    const value = meta[key];
    if (typeof value === "string") return value;
    if (Array.isArray(value) && value.length > 0) return String(value[0]);
    return "";
  });
}

function applyRoutesToMatches(store: GraphStore, rule: AstGrepRule, matches: SgMatch[]): number {
  let errors = 0;
  for (const match of matches) {
    const rawMethod = metaValue(match.metaVariables, "METHOD");
    const rawPath = metaValue(match.metaVariables, "PATH");
    if (!rawMethod || !rawPath) continue;
    const method = rawMethod.toUpperCase();
    const path = rawPath.replace(/^['"]|['"]$/g, "");
    const endpointId = renderTemplate(rule.produces.to_template!, { ...match.metaVariables, METHOD: method, PATH: path });
    for (const handlerName of metaValues(match.metaVariables, rule.produces.from_capture ?? "")) {
      const handlerNode = store.findNodes(handlerName, match.file)[0];
      if (!handlerNode) continue;
      const endpointNode: GraphNode = {
        id: endpointId,
        kind: "endpoint",
        name: endpointId,
        file: match.file,
        start_line: match.line,
        end_line: match.line,
        content_hash: handlerNode.content_hash,
      };
      try {
        store.addNode(endpointNode);
        store.addEdge({
          source: handlerNode.id,
          target: endpointId,
          kind: "routes_to",
          provenance: {
            source: "ast-grep",
            confidence: rule.produces.confidence,
            evidence: `${rule.name}@${match.file}:${match.line}:${match.column}`,
            content_hash: handlerNode.content_hash,
          },
          created_at: Date.now(),
        });
      } catch {
        errors++;
      }
    }
  }
  return errors;
}

function smallestContainingFunction(nodes: import("../graph/types.js").GraphNode[], line: number): import("../graph/types.js").GraphNode | null {
  const candidates = nodes.filter(
    (n) => n.kind === "function" && n.start_line <= line && (n.end_line ?? n.start_line) >= line,
  );
  if (candidates.length === 0) return null;
  const span = (n: GraphNode) => (n.end_line ?? n.start_line) - n.start_line;
  return candidates.sort(
    (a, b) => span(a) - span(b) || a.start_line - b.start_line || a.id.localeCompare(b.id),
  )[0]!;
}

function applyRendersMatches(store: GraphStore, rule: AstGrepRule, matches: SgMatch[]): number {
  let errors = 0;
  for (const match of matches) {
    const targetName = metaValue(match.metaVariables, rule.produces.to_capture ?? "");
    if (!targetName) continue;
    const sourceNode = smallestContainingFunction(store.getNodesByFile(match.file), match.line);
    if (!sourceNode) continue;
    const targetNode = store.findNodes(targetName, match.file)[0];
    if (!targetNode) continue;
    try {
      store.addEdge({
        source: sourceNode.id,
        target: targetNode.id,
        kind: "renders",
        provenance: {
          source: "ast-grep",
          confidence: rule.produces.confidence,
          evidence: `${rule.name}@${match.file}:${match.line}:${match.column}`,
          content_hash: sourceNode.content_hash,
        },
        created_at: Date.now(),
      });
    } catch {
      errors++;
    }
  }
  return errors;
}
export function applyRuleMatches(store: GraphStore, rule: AstGrepRule, matches: SgMatch[]): number {
  if (rule.produces.edge_kind === "routes_to") return applyRoutesToMatches(store, rule, matches);
  if (rule.produces.edge_kind === "renders") return applyRendersMatches(store, rule, matches);
  return 0;
}
export async function runAstGrepIndexStage(
  store: GraphStore,
  projectRoot: string,
  files: string[],
  scanFn: typeof runScan = runScan,
): Promise<number> {
  let errors = 0;
  if (files.length === 0) return errors;
  const bundledDir = fileURLToPath(new URL("../rules/", import.meta.url));
  const rules = loadRules({ bundledDir, projectRoot });
  for (const rule of rules) {
    const matches = await scanFn(projectRoot, rule, files);
    errors += applyRuleMatches(store, rule, matches);
  }
  return errors;
}

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { isAbsolute, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import type { GraphStore, TestTraceRecord } from "../graph/store.js";
import type { GraphNode } from "../graph/types.js";

export interface NormalizedCoverageRecord {
  reportFile: string;
  file: string;
  functionName: string;
  startOffset: number;
  endOffset: number;
  startLine: number;
  endLine: number;
  count: number;
}

function toPosixPath(value: string): string {
  return value.split("\\").join("/");
}

function countLineAtOffset(content: string, offset: number): number {
  let line = 1;
  for (let index = 0; index < Math.min(offset, content.length); index++) {
    if (content[index] === "\n") line++;
  }
  return line;
}

function isProjectLocalTsFile(projectRoot: string, filePath: string): boolean {
  const resolvedRoot = resolve(projectRoot);
  const resolvedFile = resolve(filePath);
  if (!resolvedFile.startsWith(resolvedRoot)) return false;
  return resolvedFile.endsWith(".ts") || resolvedFile.endsWith(".tsx");
}

export function parseCoverageReports(projectRoot: string, coverageDir: string): NormalizedCoverageRecord[] {
  if (!existsSync(coverageDir)) return [];

  const records: NormalizedCoverageRecord[] = [];
  const fileNames = readdirSync(coverageDir)
    .filter((name) => name.endsWith(".json"))
    .sort((a, b) => a.localeCompare(b));
  const fileContentCache = new Map<string, string>();

  for (const fileName of fileNames) {
    let raw: { result?: unknown[] };
    try {
      raw = JSON.parse(readFileSync(resolve(coverageDir, fileName), "utf8")) as { result?: unknown[] };
    } catch {
      continue;
    }

    for (const entry of raw.result ?? []) {
      try {
        if (!entry || typeof entry !== "object") continue;
        const url = (entry as { url?: unknown }).url;
        const functions = (entry as { functions?: unknown }).functions;
        if (typeof url !== "string" || !Array.isArray(functions)) continue;

        const filePath = url.startsWith("file://") ? fileURLToPath(url) : url;
        if (!isAbsolute(filePath) || !isProjectLocalTsFile(projectRoot, filePath)) continue;

        const content = fileContentCache.get(filePath) ?? readFileSync(filePath, "utf8");
        fileContentCache.set(filePath, content);
        const relFile = toPosixPath(relative(projectRoot, filePath));

        for (const fn of functions) {
          if (!fn || typeof fn !== "object") continue;
          const functionName = (fn as { functionName?: unknown }).functionName;
          const ranges = (fn as { ranges?: unknown }).ranges;
          if (typeof functionName !== "string" || !Array.isArray(ranges)) continue;

          const firstCoveredRange = ranges.find((range) => {
            if (!range || typeof range !== "object") return false;
            const count = (range as { count?: unknown }).count;
            return typeof count === "number" && count > 0;
          }) as { startOffset: number; endOffset: number; count: number } | undefined;

          if (!firstCoveredRange) continue;
          if (typeof firstCoveredRange.startOffset !== "number") continue;
          if (typeof firstCoveredRange.endOffset !== "number") continue;
          if (typeof firstCoveredRange.count !== "number") continue;

          records.push({
            reportFile: fileName,
            file: relFile,
            functionName,
            startOffset: firstCoveredRange.startOffset,
            endOffset: firstCoveredRange.endOffset,
            startLine: countLineAtOffset(content, firstCoveredRange.startOffset),
            endLine: countLineAtOffset(content, firstCoveredRange.endOffset),
            count: firstCoveredRange.count,
          });
        }
      } catch {
        continue;
      }
    }
  }

  return records.sort((a, b) => {
    return a.reportFile.localeCompare(b.reportFile)
      || a.file.localeCompare(b.file)
      || a.functionName.localeCompare(b.functionName)
      || a.startLine - b.startLine
      || a.endLine - b.endLine;
  });
}

export interface MappedCoverageRecord extends NormalizedCoverageRecord {
  node: GraphNode;
}

function lineSpan(node: GraphNode): number {
  return (node.end_line ?? node.start_line) - node.start_line;
}

function overlaps(node: GraphNode, startLine: number, endLine: number): boolean {
  const nodeEnd = node.end_line ?? node.start_line;
  return node.start_line <= endLine && nodeEnd >= startLine;
}

export function mapCoverageToNodes(store: GraphStore, records: NormalizedCoverageRecord[]): MappedCoverageRecord[] {
  const mapped: MappedCoverageRecord[] = [];

  for (const record of records) {
    const candidates = store
      .getNodesByFile(record.file)
      .filter((node) => overlaps(node, record.startLine, record.endLine))
      .sort((a, b) => lineSpan(a) - lineSpan(b) || a.start_line - b.start_line || a.id.localeCompare(b.id));

    const resolved = candidates[0];
    if (!resolved) continue;
    mapped.push({ ...record, node: resolved });
  }

  return mapped.sort((a, b) => {
    return a.reportFile.localeCompare(b.reportFile)
      || a.file.localeCompare(b.file)
      || a.startLine - b.startLine
      || a.node.id.localeCompare(b.node.id);
  });
}

export function runCoverageIndexStage(store: GraphStore, projectRoot: string, coverageDir: string): void {
  const normalized = parseCoverageReports(projectRoot, coverageDir);
  const mapped = mapCoverageToNodes(store, normalized);
  const byReport = new Map<string, MappedCoverageRecord[]>();

  for (const record of mapped) {
    const group = byReport.get(record.reportFile) ?? [];
    group.push(record);
    byReport.set(record.reportFile, group);
  }

  const reportNames = [...byReport.keys()].sort((a, b) => a.localeCompare(b));
  for (const reportFile of reportNames) {
    const group = byReport.get(reportFile)!;
    const tests = group
      .filter((record) => record.node.kind === "test" || record.file.endsWith(".test.ts") || record.file.endsWith(".spec.ts"))
      .sort((a, b) => a.node.id.localeCompare(b.node.id));
    const production = group
      .filter((record) => record.node.kind !== "test" && !record.file.endsWith(".test.ts") && !record.file.endsWith(".spec.ts"))
      .sort((a, b) => a.file.localeCompare(b.file) || a.startLine - b.startLine || a.node.id.localeCompare(b.node.id));

    for (const testRecord of tests) {
      for (const prodRecord of production) {
        store.addEdge({
          source: prodRecord.node.id,
          target: testRecord.node.id,
          kind: "tested_by",
          provenance: {
            source: "coverage",
            confidence: 1,
            evidence: `${reportFile}:${testRecord.file}:${testRecord.startLine}`,
            content_hash: prodRecord.node.content_hash,
          },
          created_at: Date.now(),
        });
      }

      const trace: TestTraceRecord = {
        testNodeId: testRecord.node.id,
        steps: [
          { nodeId: testRecord.node.id, ordinal: 0, contentHash: testRecord.node.content_hash },
          ...production.map((record, index) => ({
            nodeId: record.node.id,
            ordinal: index + 1,
            contentHash: record.node.content_hash,
          })),
        ],
      };
      store.saveTestTrace(trace);
    }
  }
  try {
    store.markCoverageIndexed();
  } catch {
    // readonly DB or other write failure: leave sentinel unset
  }
}

import { execSync } from "node:child_process";
import type { GraphStore } from "../graph/store.js";

const GIT_HEAD_KEY = "__git_cochange_head__";

export interface GitCoChangeOptions {
  minCoChangeCount?: number;
  windowDays?: number;
}

interface CommitRecord {
  hash: string;
  dateIso: string;
  files: string[];
}

function parseGitLog(projectRoot: string): CommitRecord[] {
  let stdout: string;
  try {
    stdout = execSync(
      'git log --name-only --format="__COMMIT__%H %aI" --diff-filter=AMRT',
      {
        cwd: projectRoot,
        encoding: "utf8",
        maxBuffer: 50 * 1024 * 1024,
        stdio: ["ignore", "pipe", "ignore"],
      },
    );
  } catch {
    return [];
  }

  const records: CommitRecord[] = [];
  let current: CommitRecord | null = null;

  for (const rawLine of stdout.split("\n")) {
    const line = rawLine.trim();
    if (!line) continue;

    if (line.startsWith("__COMMIT__")) {
      if (current && current.files.length > 0) records.push(current);
      const rest = line.slice("__COMMIT__".length);
      const spaceIdx = rest.indexOf(" ");
      const hash = rest.slice(0, spaceIdx);
      const dateIso = rest.slice(spaceIdx + 1);
      current = { hash, dateIso, files: [] };
    } else if (current) {
      current.files.push(line.split("\\").join("/"));
    }
  }

  if (current && current.files.length > 0) records.push(current);

  return records;
}

function computeDecayWeight(commitDateIso: string, now: number, halfLifeDays: number): number {
  const commitTime = new Date(commitDateIso).getTime();
  const ageDays = (now - commitTime) / (1000 * 60 * 60 * 24);
  return Math.pow(0.5, ageDays / halfLifeDays);
}

function getCurrentHead(projectRoot: string): string | null {
  try {
    return execSync("git rev-parse HEAD", {
      cwd: projectRoot,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
  } catch {
    return null;
  }
}

export async function runGitCoChangeStage(
  store: GraphStore,
  projectRoot: string,
  options: GitCoChangeOptions = {},
): Promise<number> {
  let errors = 0;
  const head = getCurrentHead(projectRoot);
  if (!head) return errors;
  const lastHead = store.getFileHash(GIT_HEAD_KEY);
  if (lastHead === head) return errors;
  const oldEdges = store.queryRows<{ source: string; target: string }>(
    "SELECT source, target FROM edges WHERE kind = 'co_changes_with' AND provenance_source = 'git'",
  );
  for (const edge of oldEdges) {
    try {
      store.deleteEdge(edge.source, edge.target, "co_changes_with", "git");
    } catch {
      errors++;
    }
  }
  const minCount = options.minCoChangeCount ?? 2;
  const windowDays = options.windowDays ?? 365;
  const commits = parseGitLog(projectRoot);
  if (commits.length === 0) {
    try {
      store.setFileHash(GIT_HEAD_KEY, head);
    } catch {
      errors++;
    }
    return errors;
  }
  const now = Date.now();
  const halfLifeDays = windowDays / 4;
  const trackedFiles = new Set(store.listFiles());
  const pairCounts = new Map<string, { count: number; weightedScore: number }>();
  for (const commit of commits) {
    const relevantFiles = commit.files.filter((f) => trackedFiles.has(f)).sort();
    if (relevantFiles.length < 2) continue;
    const weight = computeDecayWeight(commit.dateIso, now, halfLifeDays);
    for (let i = 0; i < relevantFiles.length; i++) {
      for (let j = i + 1; j < relevantFiles.length; j++) {
        const key = `${relevantFiles[i]}|${relevantFiles[j]}`;
        const existing = pairCounts.get(key) ?? { count: 0, weightedScore: 0 };
        existing.count++;
        existing.weightedScore += weight;
        pairCounts.set(key, existing);
      }
    }
  }
  for (const [key, data] of pairCounts) {
    if (data.count < minCount) continue;
    const [fileA, fileB] = key.split("|");
    const nodeA = store.findNodes(fileA!)[0];
    const nodeB = store.findNodes(fileB!)[0];
    if (!nodeA || !nodeB) continue;
    const evidence = `co_changes: ${data.count}, recency_score: ${data.weightedScore.toFixed(1)}, window: ${windowDays}d`;
    try {
      store.addEdge({
        source: nodeA.id,
        target: nodeB.id,
        kind: "co_changes_with",
        provenance: {
          source: "git",
          confidence: Math.min(0.9, 0.3 + data.count * 0.1),
          evidence,
          content_hash: nodeA.content_hash,
        },
        created_at: Date.now(),
      });
    } catch {
      errors++;
    }
  }

  try {
    store.setFileHash(GIT_HEAD_KEY, head);
  } catch {
    errors++;
  }
  return errors;
}

import type { GraphStore, NeighborResult } from "../graph/store.js";
import type { GraphEdge, GraphNode } from "../graph/types.js";
import {
  computeAnchor,
  rankNeighbors,
  formatNeighborhood,
  formatAnchorLocation,
  type AnchoredNeighbor,
  type NeighborSection,
  type NamedSection,
} from "../output/anchoring.js";
import { evaluateFreshness, prependFreshnessHeader } from "../output/freshness.js";
import { createSignalComputer, type NodeSignals } from "../output/signals.js";
import { renderSymbolCardBody, renderSymbolSourceSection } from "./symbol-card.js";
import { renderSymbolContractBody } from "./symbol-contract.js";

export interface SymbolGraphParams {
  name: string;
  file?: string;
  include?: Array<"neighborhood" | "contract" | "source">;
  limit?: number;
  store: GraphStore;
  projectRoot: string;
}

export interface RenderedSymbolNeighborhood {
  body: string;
  hasLocalExceptions: boolean;
}

function isAgentEdgeStale(nr: NeighborResult, store: GraphStore): boolean {
  if (nr.edge.provenance.source !== "agent") return false;
  const sourceNode = store.getNode(nr.edge.source);
  if (!sourceNode) return true;
  const currentFileHash = store.getFileHash(sourceNode.file);
  if (!currentFileHash) return true;
  return nr.edge.provenance.content_hash !== currentFileHash;
}

function toAnchoredNeighbor(
  nr: NeighborResult,
  projectRoot: string,
  store: GraphStore,
  computeSignals?: (nodeId: string) => NodeSignals,
): AnchoredNeighbor {
  const anchor = computeAnchor(nr.node, projectRoot);
  const agentStale = isAgentEdgeStale(nr, store);
  const effectiveAnchor = agentStale ? { ...anchor, stale: true } : anchor;
  return {
    anchor: effectiveAnchor,
    name: nr.node.name,
    edgeKind: nr.edge.kind,
    confidence: nr.edge.provenance.confidence,
    provenanceSource: nr.edge.provenance.source,
    signals: computeSignals ? computeSignals(nr.node.id) : undefined,
  };
}

function buildSection(
  neighbors: NeighborResult[],
  limit: number,
  projectRoot: string,
  store: GraphStore,
  computeSignals?: (nodeId: string) => NodeSignals,
): NeighborSection {
  const ranked = rankNeighbors(neighbors, limit);
  return {
    items: ranked.kept.map((nr) => toAnchoredNeighbor(nr, projectRoot, store, computeSignals)),
    omitted: ranked.omitted,
  };
}

function hasStaleItems(section: NeighborSection): boolean {
  return section.items.some((item) => item.anchor.stale);
}

/** Map (edgeKind, direction) to a human-readable section title. */
function sectionTitle(edgeKind: string, direction: "in" | "out"): string {
  switch (edgeKind) {
    case "calls":
      return direction === "in" ? "Callers" : "Callees";
    case "imports":
      return direction === "in" ? "Imported By" : "Imports";
    case "implements":
      return direction === "in" ? "Implemented By" : "Implements";
    case "extends":
      return direction === "in" ? "Extended By" : "Extends";
    case "tested_by":
      return direction === "in" ? "Tested By" : "Tests";
    case "co_changes_with":
      return "Co-changes With";
    case "renders":
      return direction === "in" ? "Rendered By" : "Renders";
    case "routes_to":
      return direction === "in" ? "Routed From" : "Routes To";
    default: {
      const label = edgeKind.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
      return direction === "in" ? `${label} (incoming)` : `${label} (outgoing)`;
    }
  }
}

export function renderLegacyNeighborhoodBody(params: SymbolGraphParams): RenderedSymbolNeighborhood {
  const { name, file, limit = 10, store, projectRoot } = params;
  const nodes = store.findNodes(name, file);
  if (nodes.length === 0) {
    return { body: `Symbol "${name}" not found`, hasLocalExceptions: false };
  }
  if (nodes.length > 1) {
    const lines: string[] = [`Multiple matches for "${name}":\n`];
    for (const node of nodes) {
      const anchor = computeAnchor(node, projectRoot);
      const staleMarker = anchor.stale ? " [stale]" : "";
      lines.push(`  ${formatAnchorLocation(anchor)}  ${node.name} (${node.kind})${staleMarker}`);
    }
    return {
      body: `${lines.join("\n")}\n`,
      hasLocalExceptions: lines.some((line) => line.includes("[stale]")),
    };
  }
    const node = nodes[0]!;
  const symbolAnchor = computeAnchor(node, projectRoot);
  const signalComputer = createSignalComputer(store);
  const allNeighbors = store.getNeighbors(node.id);
    const computeSignals = (nodeId: string) => signalComputer.compute(nodeId);
  const buckets = new Map<string, NeighborResult[]>();
    const unresolvedResults: NeighborResult[] = [];
  for (const nr of allNeighbors) {
    if (nr.node.file.startsWith("__meta__")) continue;
    if (nr.node.file.startsWith("__unresolved__")) {
      unresolvedResults.push(nr);
      continue;
    }
      const direction = nr.edge.target === node.id ? "in" : "out";
    const title = sectionTitle(nr.edge.kind, direction);
    const bucket = buckets.get(title) ?? [];
    bucket.push(nr);
    buckets.set(title, bucket);
  }
    const sectionOrder = [
    "Callers", "Callees", "Imports", "Imported By",
    "Implemented By", "Implements",
    "Extended By", "Extends",
    "Tested By", "Tests",
    "Co-changes With",
    "Rendered By", "Renders",
    "Routed From", "Routes To",
  ];
    const namedSections: NamedSection[] = [];
  for (const title of sectionOrder) {
    const bucket = buckets.get(title);
    if (bucket && bucket.length > 0) {
      namedSections.push({ title, section: buildSection(bucket, limit, projectRoot, store, computeSignals) });
      buckets.delete(title);
    }
  }
    for (const [title, bucket] of buckets) {
    if (bucket.length > 0) {
      namedSections.push({ title, section: buildSection(bucket, limit, projectRoot, store, computeSignals) });
    }
  }
    if (unresolvedResults.length > 0) {
    namedSections.push({ title: "Unresolved", section: buildSection(unresolvedResults, limit, projectRoot, store) });
  }
  return {
    body: formatNeighborhood(
      { name: node.name, kind: node.kind, anchor: symbolAnchor, signals: signalComputer.compute(node.id) },
      namedSections,
    ),
    hasLocalExceptions: symbolAnchor.stale || namedSections.some((ns) => hasStaleItems(ns.section)),
  };
}

function collectVisibleNeighborhoodScope(params: SymbolGraphParams, node: GraphNode): {
  resultNodes: GraphNode[];
  resultEdges: GraphEdge[];
} {
  const limit = params.limit ?? 10;
  const buckets = new Map<string, NeighborResult[]>();
  const unresolvedResults: NeighborResult[] = [];

  for (const nr of params.store.getNeighbors(node.id)) {
    if (nr.node.file.startsWith("__meta__")) continue;
    if (nr.node.file.startsWith("__unresolved__")) {
      unresolvedResults.push(nr);
      continue;
    }
    const direction = nr.edge.target === node.id ? "in" : "out";
    const title = sectionTitle(nr.edge.kind, direction);
    const bucket = buckets.get(title) ?? [];
    bucket.push(nr);
    buckets.set(title, bucket);
  }

  const sectionOrder = [
    "Callers", "Callees", "Imports", "Imported By",
    "Implemented By", "Implements",
    "Extended By", "Extends",
    "Tested By", "Tests",
    "Co-changes With",
    "Rendered By", "Renders",
    "Routed From", "Routes To",
  ];
  const visible: NeighborResult[] = [];
  for (const title of sectionOrder) {
    const bucket = buckets.get(title);
    if (bucket && bucket.length > 0) {
      visible.push(...rankNeighbors(bucket, limit).kept);
      buckets.delete(title);
    }
  }
  for (const bucket of buckets.values()) visible.push(...rankNeighbors(bucket, limit).kept);
  visible.push(...rankNeighbors(unresolvedResults, limit).kept);

  return {
    resultNodes: visible
      .filter((nr) => !nr.node.file.startsWith("__unresolved__"))
      .map((nr) => nr.node),
    resultEdges: visible.map((nr) => nr.edge),
  };
}

function collectDefaultCardScope(params: SymbolGraphParams, node: GraphNode): {
  resultNodes: GraphNode[];
  resultEdges: GraphEdge[];
} {
  const allNeighbors = params.store.getNeighbors(node.id).filter(
    (nr) => !nr.node.file.startsWith("__meta__") && !nr.node.file.startsWith("__unresolved__"),
  );
  const tests = allNeighbors.filter((nr) => nr.edge.kind === "tested_by" && nr.edge.source === node.id);
  const callers = allNeighbors.filter((nr) => nr.edge.kind === "calls" && nr.edge.target === node.id).slice(0, 5);
  const callees = allNeighbors.filter((nr) => nr.edge.kind === "calls" && nr.edge.source === node.id).slice(0, 5);
  const imports = allNeighbors.filter((nr) => nr.edge.kind === "imports" && nr.edge.source === node.id).slice(0, 5);
  const extendsOut = allNeighbors.filter((nr) => nr.edge.kind === "extends" && nr.edge.source === node.id).slice(0, 5);
  const implementsOut = allNeighbors.filter((nr) => nr.edge.kind === "implements" && nr.edge.source === node.id).slice(0, 5);
  const visible = [...tests, ...callers, ...callees, ...imports, ...extendsOut, ...implementsOut];
  return {
    resultNodes: visible.map((nr) => nr.node),
    resultEdges: visible.map((nr) => nr.edge),
  };
}

function collectSymbolGraphScope(params: SymbolGraphParams): {
  targetNodes: GraphNode[];
  resultNodes: GraphNode[];
  resultEdges: GraphEdge[];
} {
  const resolvedNodes = params.store.findNodes(params.name, params.file);
  const targetNodes = resolvedNodes.length === 1 ? [resolvedNodes[0]!] : [];
  const resultNodes = new Map<string, GraphNode>();
  const resultEdges: GraphEdge[] = [];

  for (const node of resolvedNodes) resultNodes.set(node.id, node);
  if (resolvedNodes.length === 1) {
    const node = resolvedNodes[0]!;
    const scoped = (params.include ?? []).includes("neighborhood")
      ? collectVisibleNeighborhoodScope(params, node)
      : collectDefaultCardScope(params, node);
    for (const resultNode of scoped.resultNodes) resultNodes.set(resultNode.id, resultNode);
    resultEdges.push(...scoped.resultEdges);
  }

  return { targetNodes, resultNodes: [...resultNodes.values()], resultEdges };
}
export function symbolGraph(params: SymbolGraphParams): string {
  const { include } = params;
  const resolvedNodes = params.store.findNodes(params.name, params.file);
  const useNeighborhoodBase = (include ?? []).includes("neighborhood");
  const base = useNeighborhoodBase
    ? renderLegacyNeighborhoodBody(params)
    : renderSymbolCardBody({
        name: params.name,
        file: params.file,
        store: params.store,
        projectRoot: params.projectRoot,
      });
  let body = base.body;
  if (resolvedNodes.length === 1 && (include ?? []).includes("contract")) {
    const renderedContract = renderSymbolContractBody({
      name: params.name,
      file: params.file,
      store: params.store,
      projectRoot: params.projectRoot,
    });
    body = `${body}${body.endsWith("\n") ? "\n" : "\n\n"}${renderedContract.body}`;
  }

  if (resolvedNodes.length === 1 && (include ?? []).includes("source")) {
    const renderedSource = renderSymbolSourceSection({
      name: params.name,
      file: params.file,
      store: params.store,
      projectRoot: params.projectRoot,
    });
    body = `${body}${body.endsWith("\n") ? "\n" : "\n\n"}${renderedSource.body}`;
  }

  const freshness = evaluateFreshness({
    store: params.store,
    projectRoot: params.projectRoot,
    ...collectSymbolGraphScope(params),
  });
  return prependFreshnessHeader(body, freshness);
}

import type { GraphStore, NeighborResult } from "../graph/store.js";
import { computeAnchor, formatAnchorLocation } from "../output/anchoring.js";
import { createSignalComputer, formatImpactWhy, type NodeSignals, type SignalComputer } from "../output/signals.js";
import { evaluateFreshness, prependFreshnessHeader } from "../output/freshness.js";
import { resolveUniqueSymbol } from "./symbol-resolution.js";

export type ChangeType = "signature_change" | "removal" | "behavior_change" | "addition";
export type ImpactClassification = "breaking" | "behavioral";

export interface CollectImpactParams {
  symbols: string[];
  changeType: ChangeType;
  store: GraphStore;
  maxDepth?: number;
  signalComputer?: SignalComputer;
}
export interface ImpactItem {
  nodeId: string;
  name: string;
  file: string;
  depth: number;
  classification: ImpactClassification;
}

export interface ImpactDetail extends ImpactItem {
  chainConfidence: number;
  signals: NodeSignals;
  edge: NeighborResult["edge"];
}

interface QueueItem {
  id: string;
  depth: number;
  chainConfidence: number;
}

function classify(changeType: ChangeType, depth: number): ImpactClassification | null {
  if (changeType === "addition") return null;
  if (changeType === "behavior_change") return "behavioral";
  if (changeType === "signature_change" || changeType === "removal") {
    return depth === 1 ? "breaking" : "behavioral";
  }
  return null;
}

function dedupeInboundByStrongestEdge(inbound: NeighborResult[]): NeighborResult[] {
  const bestByNode = new Map<string, NeighborResult>();
  for (const hit of inbound) {
    const existing = bestByNode.get(hit.node.id);
    if (!existing || hit.edge.provenance.confidence > existing.edge.provenance.confidence) {
      bestByNode.set(hit.node.id, hit);
    }
  }
  return [...bestByNode.values()];
}

function compareDetails(a: ImpactDetail, b: ImpactDetail): number {
  if (a.classification !== b.classification) return a.classification === "breaking" ? -1 : 1;
  if (a.signals.fanIn !== b.signals.fanIn) return b.signals.fanIn - a.signals.fanIn;
  if (a.signals.tested !== b.signals.tested) return a.signals.tested ? 1 : -1;
  if (a.signals.coChangeScore !== b.signals.coChangeScore) return b.signals.coChangeScore - a.signals.coChangeScore;
  if (a.chainConfidence !== b.chainConfidence) return b.chainConfidence - a.chainConfidence;
  if (a.depth !== b.depth) return a.depth - b.depth;
  return a.file.localeCompare(b.file) || a.name.localeCompare(b.name);
}

export function collectImpactDetails(params: CollectImpactParams): ImpactDetail[] {
  const { symbols, changeType, store, maxDepth = 5, signalComputer: providedSignalComputer } = params;
  if (changeType === "addition") return [];

  const queue: QueueItem[] = [];
  const seen = new Map<string, { depth: number; chainConfidence: number }>();
  const detailsByNode = new Map<string, ImpactDetail>();

  const changedNodeIds: string[] = [];
  for (const symbol of symbols) {
    for (const node of store.findNodes(symbol)) {
      queue.push({ id: node.id, depth: 0, chainConfidence: 1 });
      seen.set(node.id, { depth: 0, chainConfidence: 1 });
      changedNodeIds.push(node.id);
    }
  }

  const signalComputer = providedSignalComputer ?? createSignalComputer(store);

  while (queue.length > 0) {
    const current = queue.shift()!;
    if (current.depth >= maxDepth) continue;

    const inboundCalls = store.getNeighbors(current.id, { direction: "in", kind: "calls" });
    const inboundImplements = store.getNeighbors(current.id, { direction: "in", kind: "implements" });
    const inbound = dedupeInboundByStrongestEdge([...inboundCalls, ...inboundImplements]);

    for (const neighbor of inbound) {
      const depth = current.depth + 1;
      const chainConfidence = Math.min(current.chainConfidence, neighbor.edge.provenance.confidence);
      const existing = seen.get(neighbor.node.id);

      if (existing && (existing.depth < depth || (existing.depth === depth && existing.chainConfidence >= chainConfidence))) {
        continue;
      }

      seen.set(neighbor.node.id, { depth, chainConfidence });
      queue.push({ id: neighbor.node.id, depth, chainConfidence });

      const classification = classify(changeType, depth);
      if (!classification) continue;

      detailsByNode.set(neighbor.node.id, {
        nodeId: neighbor.node.id,
        name: neighbor.node.name,
        file: neighbor.node.file,
        depth,
        classification,
        chainConfidence,
        signals: signalComputer.compute(neighbor.node.id, changedNodeIds),
        edge: neighbor.edge,
      });
    }
  }

  return [...detailsByNode.values()].sort(compareDetails);
}

export function collectImpact(params: CollectImpactParams): ImpactItem[] {
  return collectImpactDetails(params).map(({ nodeId, name, file, depth, classification }) => ({
    nodeId,
    name,
    file,
    depth,
    classification,
  }));
}

function buildEmptyImpactDiagnostic(
  symbols: string[],
  store: GraphStore,
  signalComputer: SignalComputer,
  maxDepth: number,
): string {
  const lines: string[] = [];
  for (const symbol of symbols) {
    const matches = store.findNodes(symbol);
    const node = matches.length === 1 ? matches[0]! : null;
    if (!node) {
      lines.push(`No dependents found for '${symbol}' within depth ${maxDepth}.`);
      continue;
    }
    const signals = signalComputer.compute(node.id, []);
    if (node.kind === "interface") {
      lines.push(
        `No call-edge dependents found for interface '${node.name}'. Consider checking implementors via symbol_graph.`,
      );
    } else if (signals.roles.includes("entry-point")) {
      lines.push(`No dependents found — '${node.name}' is an entry point with no callers.`);
    } else {
      lines.push(`No dependents found for '${node.name}' within depth ${maxDepth}.`);
    }
  }
  return `${lines.join("\n")}\n`;
}

export function impact(params: {
  symbols: string[];
  changeType: ChangeType;
  store: GraphStore;
  projectRoot: string;
  maxDepth?: number;
}): string {
  const targetNodes = (params.symbols ?? []).flatMap((symbol) => params.store.findNodes(symbol));
  const withFreshness = (
    body: string,
    resultNodes = targetNodes,
    resultEdges: NeighborResult["edge"][] = [],
  ) => prependFreshnessHeader(
    body,
    evaluateFreshness({
      store: params.store,
      projectRoot: params.projectRoot,
      targetNodes,
      resultNodes,
      resultEdges,
      recommendation: "impact may be incomplete; refresh index before relying on this result",
    }),
  );

  // Defensive: validate symbols parameter (#065)
  if (!params.symbols || params.symbols.length === 0) {
    return withFreshness(
      "Error: 'symbols' parameter is required. Provide one or more symbol names to analyze impact.\n\nExample: impact({ symbols: [\"functionName\"], changeType: \"behavior_change\" })\n",
    );
  }

  // Defensive: validate changeType (#065)
  const validChangeTypes: ChangeType[] = ["signature_change", "removal", "behavior_change", "addition"];
  if (!validChangeTypes.includes(params.changeType)) {
    return withFreshness(
      `Error: Invalid changeType "${params.changeType}". Must be one of: ${validChangeTypes.join(", ")}\n`,
    );
  }

  for (const symbol of params.symbols) {
    const resolved = resolveUniqueSymbol({
      name: symbol,
      store: params.store,
      projectRoot: params.projectRoot,
      notFoundLabel: "Symbol",
    });
    if (resolved.kind === "ambiguous") return withFreshness(resolved.text);
    if (resolved.kind === "not_found") return withFreshness(resolved.text);
  }

  if (params.changeType === "addition") {
    return withFreshness(
      `addition: impact analysis for additions is not yet supported — use symbol_graph to inspect the new symbol's neighborhood\n`,
    );
  }

  const signalComputer = createSignalComputer(params.store);
  const hits = collectImpactDetails({
    symbols: params.symbols,
    changeType: params.changeType,
    store: params.store,
    maxDepth: params.maxDepth,
    signalComputer,
  });

  if (hits.length === 0) {
    const body = buildEmptyImpactDiagnostic(params.symbols, params.store, signalComputer, params.maxDepth ?? 5);
    return withFreshness(body);
  }

  const lines = hits.flatMap((hit) => {
    const node = params.store.getNode(hit.nodeId);
    if (!node) return [];
    const anchor = computeAnchor(node, params.projectRoot);
    const why = formatImpactWhy(hit.signals, hit.chainConfidence);
    return [
      `${formatAnchorLocation(anchor)}  ${hit.name}  ${hit.classification}  depth:${hit.depth}${anchor.stale ? " [stale]" : ""}  ${why}`,
    ];
  });

  const hitNodes = hits.flatMap((hit) => {
    const node = params.store.getNode(hit.nodeId);
    return node ? [node] : [];
  });
  const body = lines.length > 0 ? `${lines.join("\n")}\n` : "";
  return withFreshness(body, [...targetNodes, ...hitNodes], hits.map((hit) => hit.edge));
}

import type { GraphStore } from "../graph/store.js";
import type { GraphEdge, GraphNode } from "../graph/types.js";
import { computeAnchor, formatAnchorLocation } from "../output/anchoring.js";
import { evaluateFreshness, prependFreshnessHeader } from "../output/freshness.js";
import { createSignalComputer, formatRoleTags, type NodeRole, type SignalComputer } from "../output/signals.js";
import { resolveUniqueSymbol } from "./symbol-resolution.js";

export interface TraceParams {
  entry: string;
  file?: string;
  store: GraphStore;
  projectRoot: string;
}

function pickCoverageTraceForNode(store: GraphStore, nodeId: string): string | null {
  const coveringTests = store.getNeighbors(nodeId, { direction: "out", kind: "tested_by" }).sort((a, b) => a.node.id.localeCompare(b.node.id));
  for (const candidate of coveringTests) {
    const record = store.getTestTrace(candidate.node.id);
    if (record) return record.testNodeId;
  }
  return null;
}

function resolveCoverageTraceId(store: GraphStore, nodeId: string): string | null {
  const node = store.getNode(nodeId);
  if (!node) return null;
  if (node.kind === "test") return node.id;
  if (node.kind === "endpoint") {
    const handlers = store.getNeighbors(node.id, { direction: "in", kind: "routes_to" }).sort((a, b) => a.node.id.localeCompare(b.node.id));
    for (const handler of handlers) {
      const traceId = pickCoverageTraceForNode(store, handler.node.id);
      if (traceId) return traceId;
    }
    return null;
  }
  return pickCoverageTraceForNode(store, node.id);
}

function buildStaticTrace(store: GraphStore, startNodeId: string): string[] {
  const ordered: string[] = [];
  const seen = new Set<string>();
  const stack: string[] = [startNodeId];

  while (stack.length > 0) {
    const currentId = stack.pop()!;
    if (seen.has(currentId)) continue;
    seen.add(currentId);
    ordered.push(currentId);
    const nextNeighbors = store.getNeighbors(currentId, { direction: "out", kind: "calls" });
    const sorted = nextNeighbors.sort((a, b) =>
      a.node.file.localeCompare(b.node.file) || a.node.start_line - b.node.start_line || a.node.id.localeCompare(b.node.id)
    );
    for (let i = sorted.length - 1; i >= 0; i--) {
      if (!seen.has(sorted[i].node.id)) {
        stack.push(sorted[i].node.id);
      }
    }
  }
  return ordered;
}

function formatStoredTraceLine(
  store: GraphStore,
  nodeId: string,
  storedHash: string,
  projectRoot: string,
  signalComputer: SignalComputer,
): { line: string; stale: boolean } {
  const node = store.getNode(nodeId);
  if (!node) {
    return { line: `${nodeId}  unresolved [stale]`, stale: true };
  }
  const anchor = computeAnchor(node, projectRoot);
  const stale = anchor.stale || node.content_hash !== storedHash;
  const tags = formatRoleTags(signalComputer.compute(node.id));
  return {
    line: `${formatAnchorLocation(anchor)}  ${node.name}  ${node.kind}${stale ? " [stale]" : ""} ${tags}`,
    stale,
  };
}

function formatNodeLine(
  node: GraphNode,
  projectRoot: string,
  signalComputer: SignalComputer,
  rolesOverride?: NodeRole[],
): { line: string; stale: boolean } {
  const anchor = computeAnchor(node, projectRoot);
  const signals = signalComputer.compute(node.id);
  const tags = formatRoleTags({ ...signals, roles: rolesOverride ?? signals.roles });
  return {
    line: `${formatAnchorLocation(anchor)}  ${node.name}  ${node.kind}${anchor.stale ? " [stale]" : ""} ${tags}`,
    stale: anchor.stale,
  };
}

function formatLiveTraceLine(
  store: GraphStore,
  nodeId: string,
  projectRoot: string,
  signalComputer: SignalComputer,
  rolesOverride?: NodeRole[],
): { line: string; stale: boolean } {
  const node = store.getNode(nodeId);
  if (!node) return { line: `${nodeId}  unresolved [stale]`, stale: true };
  return formatNodeLine(node, projectRoot, signalComputer, rolesOverride);
}

function formatFileScopedMiss(name: string, requestedFile: string, nodes: GraphNode[], projectRoot: string): string {
  const sorted = [...nodes].sort((a, b) =>
    a.file.localeCompare(b.file) || a.start_line - b.start_line || a.id.localeCompare(b.id)
  );
  const lines: string[] = [`Symbol "${name}" was not found in ${requestedFile}. Matches exist in other files:`, ""];
  for (const node of sorted) {
    const anchor = computeAnchor(node, projectRoot);
    const staleMarker = anchor.stale ? " [stale]" : "";
    lines.push(`  ${formatAnchorLocation(anchor)}  ${node.name} (${node.kind})${staleMarker}`);
  }
  return `${lines.join("\n")}\n`;
}

function formatModeHeader(mode: "coverage" | "static", stale = false): string {
  const base = mode === "coverage" ? "mode: coverage" : "mode: static (heuristic, no runtime evidence)";
  return `${base}${stale ? " [stale]" : ""}`;
}

function traceFreshness(
  params: TraceParams,
  targetNode: GraphNode | null,
  nodeIds: string[],
  unresolvedItems: string[] = [],
  resultEdges: GraphEdge[] = [],
) {
  const resultNodes = nodeIds.flatMap((id) => {
    const node = params.store.getNode(id);
    return node ? [node] : [];
  });
  return evaluateFreshness({
    store: params.store,
    projectRoot: params.projectRoot,
    targetNodes: targetNode ? [targetNode] : [],
    resultNodes: targetNode ? [targetNode, ...resultNodes] : resultNodes,
    resultEdges,
    unresolvedItems,
    recommendation: "trace path may be unreliable; refresh index before relying on this result",
  });
}

function collectStaticTraceEdges(store: GraphStore, nodeIds: string[]): GraphEdge[] {
  const included = new Set(nodeIds);
  const edges: GraphEdge[] = [];
  for (const sourceId of nodeIds) {
    for (const neighbor of store.getNeighbors(sourceId, { direction: "out", kind: "calls" })) {
      if (included.has(neighbor.node.id)) edges.push(neighbor.edge);
    }
  }
  return edges;
}

export function trace(params: TraceParams): string {
  const resolved = resolveUniqueSymbol({
    name: params.entry,
    file: params.file,
    store: params.store,
    projectRoot: params.projectRoot,
    notFoundLabel: "Symbol",
  });

  const emptyFreshness = evaluateFreshness({
    store: params.store,
    projectRoot: params.projectRoot,
    recommendation: "trace path may be unreliable; refresh index before relying on this result",
  });

  if (resolved.kind === "ambiguous") {
    return prependFreshnessHeader(resolved.text, emptyFreshness);
  }
  if (resolved.kind === "not_found") {
    if (params.file) {
      const unscopedMatches = params.store.findNodes(params.entry);
      if (unscopedMatches.length > 0) {
        const freshness = evaluateFreshness({
          store: params.store,
          projectRoot: params.projectRoot,
          resultNodes: unscopedMatches,
          recommendation: "trace path may be unreliable; refresh index before relying on this result",
        });
        return prependFreshnessHeader(
          formatFileScopedMiss(params.entry, params.file, unscopedMatches, params.projectRoot),
          freshness,
        );
      }
    }
    return prependFreshnessHeader(`Symbol "${params.entry}" not found in the graph\n`, emptyFreshness);
  }

  const node = resolved.node;
  const signalComputer = createSignalComputer(params.store);
  const coverageTraceId = resolveCoverageTraceId(params.store, node.id);
  if (coverageTraceId) {
    const coverage = params.store.getTestTrace(coverageTraceId);
    if (coverage) {
      const orderedSteps = coverage.steps.sort((a, b) => a.ordinal - b.ordinal);
      const rendered = orderedSteps
        .map((step) => formatStoredTraceLine(params.store, step.nodeId, step.contentHash, params.projectRoot, signalComputer));
      const unresolvedItems = orderedSteps.filter((step) => !params.store.getNode(step.nodeId)).map((step) => step.nodeId);
      const freshness = traceFreshness(params, null, orderedSteps.map((step) => step.nodeId), unresolvedItems);
      const traceStale = rendered.some((item) => item.stale) || freshness.status !== "fresh";
      const body = `${[formatModeHeader("coverage", traceStale), ...rendered.map((item) => item.line)].join("\n")}\n`;
      return prependFreshnessHeader(body, freshness);
    }
  }

  if (node.kind === "class") {
    const classSignals = signalComputer.compute(node.id);
    const classLine = formatLiveTraceLine(
      params.store,
      node.id,
      params.projectRoot,
      signalComputer,
      classSignals.roles.filter((role) => role !== "leaf"),
    );
    const freshness = traceFreshness(params, node, [node.id]);
    const classStale = classLine.stale || freshness.status !== "fresh";
    const body = `${[
      formatModeHeader("static", classStale),
      classLine.line,
      "  → class entry: use symbol_graph to inspect methods, or trace a specific method symbol when one is available",
    ].join("\n")}\n`;
    return prependFreshnessHeader(body, freshness);
  }

  const staticNodeIds = buildStaticTrace(params.store, node.id);
  const staticSteps = staticNodeIds
    .map((step) => formatLiveTraceLine(params.store, step, params.projectRoot, signalComputer));
  const staticEdges = collectStaticTraceEdges(params.store, staticNodeIds);
  const freshness = traceFreshness(params, node, staticNodeIds, [], staticEdges);
  const staticStale = staticSteps.some((step) => step.stale) || freshness.status !== "fresh";
  const body = `${[formatModeHeader("static", staticStale), ...staticSteps.map((step) => step.line)].join("\n")}\n`;
  return prependFreshnessHeader(body, freshness);
}

import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { GraphNode } from "../graph/types.js";
import type { GraphStore } from "../graph/store.js";
import type { ITsServerClient } from "./tsserver-client.js";

function markerNodeId(kind: "callers" | "implementations", symbolId: string): string {
  return `__meta__::resolver::${kind}::${symbolId}`;
}

function hasMarker(store: GraphStore, kind: "callers" | "implementations", symbol: GraphNode): boolean {
  const id = markerNodeId(kind, symbol.id);
  if (store.getNode(id) === null) return false;
  // After a file re-index the marker node survives but its outbound edge is deleted.
  // Only treat the marker as valid when the edge still points to the symbol.
  return store.getEdgesBySource(id).some((e) => e.target === symbol.id);
}

function setMarker(store: GraphStore, kind: "callers" | "implementations", symbol: GraphNode): void {
  const id = markerNodeId(kind, symbol.id);
  store.addNode({
    id,
    kind: "module",
    name: id,
    file: "__meta__/resolver",
    start_line: 1,
    end_line: 1,
    content_hash: "meta",
  });
  store.addEdge({
    source: id,
    target: symbol.id,
    kind: "imports",
    provenance: { source: "lsp", confidence: 1, evidence: `resolved:${kind}`, content_hash: "meta" },
    created_at: Date.now(),
  });
}

function findSymbolColumn(projectRoot: string, file: string, line: number, symbolName: string): number {
  try {
    const lines = readFileSync(join(projectRoot, file), "utf8").split(/\r?\n/);
    const idx = (lines[line - 1] ?? "").indexOf(symbolName);
    return idx >= 0 ? idx + 1 : 1;
  } catch {
    return 1;
  }
}

function unresolvedNameFromTarget(target: string): string | null {
  if (!target.startsWith("__unresolved__::")) return null;
  return target.slice("__unresolved__::".length).split(":")[0] ?? null;
}

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function signatureImplementsInterface(signature: string | undefined, interfaceName: string): boolean {
  if (!signature) return false;
  const rx = new RegExp(`\\bimplements\\b[^\\{]*\\b${escapeRegex(interfaceName)}\\b`);
  return rx.test(signature);
}

function classImplementsInterface(
  projectRoot: string,
  file: string,
  className: string,
  interfaceName: string,
  signature?: string,
): boolean {
  if (signature != null) {
    return signatureImplementsInterface(signature, interfaceName);
  }

  try {
    const content = readFileSync(join(projectRoot, file), "utf8");
    const rx = new RegExp(
      `\\bclass\\s+${escapeRegex(className)}\\b[^\\{]*\\bimplements\\b[^\\{]*\\b${escapeRegex(interfaceName)}\\b`,
      "m",
    );
    return rx.test(content);
  } catch {
    return false;
  }
}

export async function resolveMissingCallers(
  node: GraphNode,
  store: GraphStore,
  projectRoot: string,
  client: ITsServerClient,
): Promise<void> {
  if (hasMarker(store, "callers", node)) return;

  const col = findSymbolColumn(projectRoot, node.file, node.start_line, node.name);
  let refs;
  try {
    refs = await client.references(node.file, node.start_line, col);
  } catch (err) {
    // If tsserver is permanently unavailable (not installed), set the marker so we
    // don't retry on every symbol_graph call.  For transient failures (crash, timeout,
    // etc.) leave the marker unset so the next call can succeed.
    if (err instanceof Error && err.message.startsWith("TsServer failed to start:")) {
      setMarker(store, "callers", node);
    }
    // Do NOT create edges here — writing lsp-provenance edges from a name-match
    // fallback would misrepresent confidence; the existing unresolved tree-sitter
    // edges already capture the same information honestly.
    return;
  }
  for (const ref of refs) {
    const callerNode = store
      .getNodesByFile(ref.file)
      .find((n) => n.kind !== "module" && n.start_line <= ref.line && (n.end_line === null || n.end_line >= ref.line));
    if (!callerNode) continue;
    if (callerNode.id === node.id) continue; // self reference/declaration

    const exists = store.getEdgesBySource(callerNode.id).some((e) => e.kind === "calls" && e.target === node.id);
    if (exists) continue;
    store.addEdge({
      source: callerNode.id,
      target: node.id,
      kind: "calls",
      provenance: {
        source: "lsp",
        confidence: 0.9,
        evidence: `${ref.file}:${ref.line}:${ref.col}`,
        content_hash: callerNode.content_hash,
      },
      created_at: Date.now(),
    });
  }

  setMarker(store, "callers", node);
}


export async function resolveImplementations(
  node: GraphNode,
  store: GraphStore,
  projectRoot: string,
  client: ITsServerClient,
): Promise<void> {
  const syncDeclaredImplementations = () => {
    const declared = new Map<string, GraphNode>();
    const classFiles = new Set(store.listFiles());
    for (const row of store.queryRows<{ file: string }>("SELECT DISTINCT file FROM nodes WHERE kind = ?", ["class"])) {
      classFiles.add(row.file);
    }

    for (const file of classFiles) {
      for (const classNode of store.getNodesByFile(file).filter((n) => n.kind === "class")) {
        if (!classImplementsInterface(projectRoot, classNode.file, classNode.name, node.name, classNode.signature)) continue;
        declared.set(classNode.id, classNode);
        const exists = store
          .getEdgesBySource(classNode.id)
          .some((e) => e.kind === "implements" && e.target === node.id && e.provenance.source === "lsp");
        if (!exists) {
          store.addEdge({
            source: classNode.id,
            target: node.id,
            kind: "implements",
            provenance: {
              source: "lsp",
              confidence: 0.9,
              evidence: `${classNode.file}:${classNode.start_line}:1`,
              content_hash: classNode.content_hash,
            },
            created_at: Date.now(),
          });
        }
      }
    }

    for (const neighbor of store.getNeighbors(node.id, { direction: "in", kind: "implements" })) {
      if (neighbor.edge.provenance.source !== "lsp") continue;
      if (declared.has(neighbor.node.id)) continue;
      store.deleteEdge(neighbor.edge.source, neighbor.edge.target, neighbor.edge.kind, neighbor.edge.provenance.source);
    }
  };

  if (hasMarker(store, "implementations", node)) {
    syncDeclaredImplementations();
    return;
  }
  const col = findSymbolColumn(projectRoot, node.file, node.start_line, node.name);
  const addFallbackImplementations = () => {
    syncDeclaredImplementations();
    setMarker(store, "implementations", node);
  };
  let impls;
  try {
    impls = await client.implementations(node.file, node.start_line, col);
  } catch {
    addFallbackImplementations();
    return;
  }
  if (!impls || impls.length === 0) {
    addFallbackImplementations();
    return;
  }
  for (const implLoc of impls) {
    const implNode = store
      .getNodesByFile(implLoc.file)
      .find((n) => n.kind === "class" && n.start_line <= implLoc.line && (n.end_line === null || n.end_line >= implLoc.line));
    if (!implNode) continue;
    if (!classImplementsInterface(projectRoot, implNode.file, implNode.name, node.name, implNode.signature)) continue;
    const exists = store.getEdgesBySource(implNode.id).some((e) => e.kind === "implements" && e.target === node.id);
    if (exists) continue;
    store.addEdge({
      source: implNode.id,
      target: node.id,
      kind: "implements",
      provenance: {
        source: "lsp",
        confidence: 0.9,
        evidence: `${implLoc.file}:${implLoc.line}:${implLoc.col}`,
        content_hash: implNode.content_hash,
      },
      created_at: Date.now(),
    });
  }
  syncDeclaredImplementations();
  setMarker(store, "implementations", node);
}

import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { GraphStore } from "../graph/store.js";

interface SessionStats {
  totalCalls: number;
  totalTokensSaved: number;
}

let session: SessionStats = { totalCalls: 0, totalTokensSaved: 0 };

export function estimateNaiveCost(files: string[], projectRoot: string): number {
  let totalBytes = 0;
  for (const file of files) {
    try {
      const content = readFileSync(join(projectRoot, file), "utf8");
      totalBytes += content.length;
    } catch {
      // File missing or unreadable — skip
    }
  }
  return Math.floor(totalBytes / 4);
}

export function trackCall(_toolName: string, naiveTokens: number, actualTokens: number): void {
  session.totalCalls += 1;
  session.totalTokensSaved += Math.max(0, naiveTokens - actualTokens);
}

export function getSessionStats(): SessionStats {
  return { ...session };
}

export function resetSession(): void {
  session = { totalCalls: 0, totalTokensSaved: 0 };
}

export function formatMetaLine(_toolName: string, naiveTokens: number, actualTokens: number): string {
  trackCall(_toolName, naiveTokens, actualTokens);
  const saved = Math.max(0, naiveTokens - actualTokens);
  return `_meta: tokens_saved:${saved} naive_tokens:${naiveTokens} actual_tokens:${actualTokens} session_calls:${session.totalCalls} session_tokens_saved:${session.totalTokensSaved}`;
}

export function collectNaiveFiles(
  toolName: string,
  params: Record<string, unknown>,
  store: GraphStore,
): string[] {
  const files = new Set<string>();

  switch (toolName) {
    case "symbol_graph":
    case "symbol_card":
    case "symbol_contract": {
      const name = params.name as string | undefined;
      const file = params.file as string | undefined;
      if (!name) break;
      const nodes = store.findNodes(name, file);
      for (const node of nodes) {
        if (!node.file.startsWith("__")) files.add(node.file);
        const neighbors = store.getNeighbors(node.id);
        for (const nr of neighbors) {
          if (!nr.node.file.startsWith("__")) files.add(nr.node.file);
        }
      }
      break;
    }

    case "impact": {
      const symbols = params.symbols as string[] | undefined;
      if (!symbols) break;
      for (const sym of symbols) {
        const nodes = store.findNodes(sym);
        for (const node of nodes) {
          if (!node.file.startsWith("__")) files.add(node.file);
          const neighbors = store.getNeighbors(node.id, { direction: "in" });
          for (const nr of neighbors) {
            if (!nr.node.file.startsWith("__")) files.add(nr.node.file);
          }
        }
      }
      break;
    }

    case "trace": {
      const entry = params.entry as string | undefined;
      const file = params.file as string | undefined;
      if (!entry) break;
      const nodes = store.findNodes(entry, file);
      if (nodes.length === 1) {
        const node = nodes[0]!;
        if (!node.file.startsWith("__")) files.add(node.file);
        const seen = new Set<string>([node.id]);
        const stack = [node.id];
        while (stack.length > 0) {
          const id = stack.pop()!;
          const callees = store.getNeighbors(id, { direction: "out", kind: "calls" });
          for (const nr of callees) {
            if (!seen.has(nr.node.id)) {
              seen.add(nr.node.id);
              if (!nr.node.file.startsWith("__")) files.add(nr.node.file);
              stack.push(nr.node.id);
            }
          }
        }
      }
      break;
    }

  }

  return Array.from(files);
}

export function appendTokenMeta(
  toolName: string,
  params: Record<string, unknown>,
  toolOutput: string,
  store: GraphStore,
  projectRoot: string,
): string {
  const naiveFiles = collectNaiveFiles(toolName, params, store);
  const naiveTokens = estimateNaiveCost(naiveFiles, projectRoot);
  const actualTokens = Math.floor(toolOutput.length / 4);
  const metaLine = formatMetaLine(toolName, naiveTokens, actualTokens);
  return `${toolOutput}\n${metaLine}`;
}

export function devMetaEnabled(env: Record<string, string | undefined> = process.env): boolean {
  const raw = env.CODEGRAPH_DEVMETA?.trim().toLowerCase();
  return raw === "1" || raw === "true" || raw === "yes" || raw === "on";
}

export function appendTokenMetaIfEnabled(
  toolName: string,
  params: Record<string, unknown>,
  toolOutput: string,
  store: GraphStore,
  projectRoot: string,
): string {
  if (!devMetaEnabled()) return toolOutput;
  return appendTokenMeta(toolName, params, toolOutput, store, projectRoot);
}

